import { Button } from '@/components/ds/ui/button';
import { Card } from '@/components/ds/ui/card';
import { DotGrid } from '@/components/ds/ui/dot-grid';
import { Section } from '@/components/ds/ui/section';
import { SectionHeading } from '@/components/ds/ui/section-heading';

export type CtaBandProps = {
	title: string;
	highlight?: string;
	sub: string;
	offer: { value: string; label: string; note: string };
	cta: { label: string; href: string };
	docs?: { label: string; href: string };
};

const ART = ['o  oo x o  o o', ' o o  o oo  x ', 'oo  x o  o o o', ' o oo  o x  o ', 'o  o oo o  oo '];

export function CtaBand({ title, highlight, sub, offer, cta, docs }: CtaBandProps) {
	return (
		<Section block="cta-band">
			<div className="rounded-window bg-tint p-1">
				<div className="relative grid gap-8 overflow-hidden rounded-card bg-surface p-8 md:grid-cols-5 md:items-center md:p-12">
					<div className="pointer-events-none absolute right-0 top-0 hidden opacity-50 lg:block"><DotGrid pattern={ART} size="sm" /></div>
					<div className="relative md:col-span-3">
						<SectionHeading title={title} highlight={highlight} sub={sub} />
					</div>
					<div className="relative md:col-span-2">
						<Card>
							<p className="text-center font-data text-stat text-brand">{offer.value}</p>
							<p className="text-center text-h5">{offer.label}</p>
							<p className="text-center text-body-sm text-fg-muted">{offer.note}</p>
							<Button variant="secondary" href={cta.href}>{cta.label}</Button>
							{docs ? <a href={docs.href} className="text-center text-body-sm text-fg-muted hover:text-brand">{docs.label}</a> : null}
						</Card>
					</div>
				</div>
			</div>
		</Section>
	);
}
